<?php
if(!access_page_allowed('category_manager'))throw new Exception('Access restricted.');
echo '<div class="page-head"><div><h1>Product Categories</h1><p>Manage main categories and subcategories. Existing product SKUs remain unchanged.</p></div><button class="btn primary" type="button" data-category-add>+ Add Category</button></div><div class="card table-wrap setup-category-list"><table class="table"><thead><tr><th>Main Category</th><th>Subcategory</th><th>Next New SKU</th><th>Status</th><th>Action</th></tr></thead><tbody>';
foreach(db()->query('SELECT * FROM managed_categories ORDER BY main_name,sub_name') as $c){$seq=category_sequence($c['main_name'],$c['sub_name']);echo '<tr><td>'.e($c['main_name']).'</td><td>'.e($c['sub_name']?:'No subcategory').'</td><td>'.e($seq['prefix'].'-'.str_pad($seq['next_number'],4,'0',STR_PAD_LEFT)).'</td><td>'.badge($c['active']?'Active':'Inactive',$c['active']?'ok':'info').'</td><td><button class="btn ghost sm" type="button" data-category-edit="'.e(json_encode(['id'=>$c['id'],'main'=>$c['main_name'],'sub'=>$c['sub_name'],'active'=>(bool)$c['active']])).'">Edit</button></td></tr>';}
echo '</tbody></table></div><dialog id="categorySetupDialog" class="setup-dialog"><form method="post" action="actions.php" class="stack"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="manage_category"><input type="hidden" name="return" value="category_manager"><input type="hidden" name="category_id" value="0"><div class="modal-head"><h3 data-category-title>Add Category</h3><button type="button" data-close-setup aria-label="Close category form">×</button></div><label>Main Category<input name="main_name" maxlength="100" required></label><label>Subcategory · Optional<input name="sub_name" maxlength="100" placeholder="Leave blank for a main category"></label><label class="setup-checkbox"><input type="checkbox" name="active" value="1" checked> Active category</label><p class="muted small">Existing product SKUs remain unchanged when categories are edited.</p><div class="modal-actions"><button type="button" class="btn ghost" data-close-setup>Cancel</button><button class="btn primary">Save Category</button></div></form></dialog>';
